css:
body {
  font-family: 'Segoe UI', 'Calibri', Arial, sans-serif;
  font-size: 10.5px;
  margin: 0;
  padding: 2px; /* ultra compact */
  color: #333;
  line-height: 1.0; /* no extra spacing between lines */
}

/* Paragraphs & headings */
p, h1, h2, h3, h4, h5 {
  margin: 1px 0; /* almost no vertical gap */
  padding: 0;
}

/* Tables */
table {
  width: 100%;
  border-collapse: collapse; /* no gaps */
  border-spacing: 0;
  margin: 0; /* remove extra space */
  font-size: 10px;
  line-height: 1.2; /* tight rows */
  page-break-inside: avoid;
}

th, td {
  border: 1px solid #999;
  padding: 0.3px 0.8px; /* minimal padding */
  vertical-align: middle;
}

th {
  background-color: #f2fdf2;
  font-weight: 600;
  color: #226622;
}

tr:nth-child(even) td {
  background-color: #f9f9f9;
}

/* Signature Section */
.signature-section {
  display: flex;
  justify-content: space-between;
  margin-top: 1px; /* much smaller */
  border-top: 1px dashed #999;
  padding-top: 1px; /* tighter */
  font-size: 10px;
  align-items: flex-start;
  gap: 5px;
}

.signature-box {
  flex: 1;
  text-align: center;
  min-width: 120px; /* smaller */
}

.signature-line {
  height: 30px; /* reduced */
  border: 1px solid #ccc;
  border-radius: 2px;
  margin-bottom: 1px;
  display: flex;
  justify-content: center;
  align-items: center;
  font-style: italic;
  color: #aaa;
  font-size: 8.5px;
}

.designation-date-row {
  display: flex;
  justify-content: space-between;
  gap: 5px;
  font-size: 8.5px;
}

.designation-date-row span {
  border-top: 1px solid #111;
  display: inline-block;
  padding-top: 1px;
  width: 48%;
  text-align: center;
  font-weight: bold;
}

/* Force single page look */
.container {
  max-width: 100%;
  overflow-x: hidden;
  page-break-inside: avoid;
}

@media print {
  body {
    font-size: 9px;
    padding: 0.2cm; /* minimal padding for print */
  }

  .signature-line {
    color: #ddd !important;
  }

  table th, table td {
    padding: 0.3px 0.8px; /* very tight print rows */
  }

  p {
    margin: 0.5px 0; /* ultra compact between paragraphs */
  }
}
